import{_ as t,I as a,g as r,j as o}from"./chunks/framework.Ha9mtr6N.js";const d=JSON.parse('{"title":"Quick Start","description":"First steps in OmniCraft ERP. Basic setup, migrating balances, and data security principles.","frontmatter":{"title":"Quick Start","description":"First steps in OmniCraft ERP. Basic setup, migrating balances, and data security principles.","order":3},"headers":[],"relativePath":"docs/getting-started.md","filePath":"docs/getting-started.md"}'),s={name:"docs/getting-started.md"};function i(n,e,l,c,u,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation Under Development</p><p><strong>Dear Users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, with regular updates and expansions, the reference materials are also being updated gradually.</p><p>At this time, please treat the documentation as a guide—it is currently incomplete, may temporarily lack descriptions for certain features, or contain minor inaccuracies.</p></div><h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>This page will guide you through the process of setting up OmniCraft ERP on your first run and seamlessly migrating data from your previous records (notebooks, Excel spreadsheets, or other software).</p><hr><h2 id="🌍-language-and-data-security" tabindex="-1">🌍 Language and Data Security <a class="header-anchor" href="#🌍-language-and-data-security" aria-label="Permalink to &quot;🌍 Language and Data Security&quot;">​</a></h2><p><strong>Localization:</strong> The program supports multiple languages and automatically detects your operating system&#39;s language on the first launch. You can always change it manually: select <strong>File ➔ Program Settings</strong> in the top menu, choose your preferred language, and restart the application.</p><p><strong>Data Security:</strong> Your data belongs entirely to you. We <strong>do not collect, store, or process your personal data or your business records</strong>. The application does not require any registration, email addresses, or phone numbers.</p><div class="info custom-block"><p class="custom-block-title">About Data Integrity and Backups</p><p>We make every effort to minimize data risks: the program features modern data protection mechanisms, the database runs in WAL mode (protecting against power failures), and it generates automatic background backups.</p><p>However, no system can guarantee data integrity with absolute certainty—data loss may still occur due to OS system failures, malicious software, hard drive wear, or other external causes. Maintaining backup copies remains your responsibility.</p><p>We highly recommend occasionally creating manual backups: <strong>File ➔ Export Data</strong>. The primary binary backup (<code>.db</code>) saves your entire system. However, as an extra safety measure, we recommend exporting your data in the second format as well—a <code>.zip</code> file containing CSV tables. If the binary database file ever suffers minor corruption from drive failures and fails to load, you will have a fallback restoration option.</p></div><hr><h2 id="🚚-migrating-data-from-previous-records" tabindex="-1">🚚 Migrating Data from Previous Records <a class="header-anchor" href="#🚚-migrating-data-from-previous-records" aria-label="Permalink to &quot;🚚 Migrating Data from Previous Records&quot;">​</a></h2><p>If you are transitioning to OmniCraft ERP from another system, you do not need to manually log every past sale from previous years. You can migrate your current &quot;snapshot&quot; of the business in two simple steps.</p><h3 id="step-1-enter-current-assets-and-materials" tabindex="-1">Step 1. Enter Current Assets and Materials <a class="header-anchor" href="#step-1-enter-current-assets-and-materials" aria-label="Permalink to &quot;Step 1. Enter Current Assets and Materials&quot;">​</a></h3><ol><li>Open the <strong>Workshop</strong> tab and enter all your current equipment and tools at their original purchase price.</li><li>Open the <strong>Materials</strong> tab and enter the actual physical balances of raw materials (for example, leather, hardware, glue, or clay) currently on your shelves.</li></ol><p><em>What happens:</em> The program will place these values on the Workshop Balance Sheet. In doing so, it will automatically record the purchase transactions in your Cash Flow Ledger. At this stage, your Cash Flow balance will logically show a deep negative value—representing the historical volume of your personal investments to get the business running.</p><h3 id="step-2-enter-historical-cash-flow-balances-and-liabilities" tabindex="-1">Step 2. Enter Historical Cash Flow Balances and Liabilities <a class="header-anchor" href="#step-2-enter-historical-cash-flow-balances-and-liabilities" aria-label="Permalink to &quot;Step 2. Enter Historical Cash Flow Balances and Liabilities&quot;">​</a></h3><p>Regardless of whether your business has already broken even or you are still returning your initial investments, you need to perform an initial correction entry. This syncs the application&#39;s math with reality.</p><p>Go to the <strong>Cash Flow</strong> tab, click the correction button, and fill in the details step-by-step:</p><ol><li><strong>Verify Historical Assets:</strong> The program will display a list of the assets you added in the <strong>Workshop</strong> tab during Step 1. Mark the items that were purchased <em>before</em> migrating to OmniCraft ERP. The program will factor their cost back into the calculations to avoid double-counting them as current expenses (since you already accounted for their purchase in your past records). <strong>Important:</strong> At this step, make sure you mark absolutely all historical equipment, tools, and consumables (excluding raw materials from the warehouse—these do not need to be marked).</li><li><strong>Enter Business Liabilities:</strong> If the workshop has any unpaid loans, borrowings, or outstanding debts to suppliers, specify them here. They will automatically be logged on your Balance Sheet as liabilities.</li><li><strong>Enter Historical Cash Flow Balance:</strong> This is the cumulative financial net result of your entire past business operation. It is calculated as follows: <strong>All Inflow</strong> (revenue from product sales, loans received, personal investments, other income) minus <strong>All Outflow</strong> (costs of raw materials, equipment purchases, rent, advertising, taxes, loan interest, and other expenses). <em>Note: This figure can be either positive or negative.</em></li></ol><div class="warning custom-block"><p class="custom-block-title">Attention: This correction can only be performed once!</p><p>This initial correction operation is locked after its first execution—it cannot be run a second time. Therefore, before clicking the confirmation button, make sure that in Step 1 you added absolutely all your old tools, machinery, and consumables to the <strong>Workshop</strong> tab.</p><p><strong>What if you later remember a forgotten historical asset?</strong> Do not worry; this can easily be corrected without disrupting your accounts:</p><ol><li>Add the forgotten machine or tool to the <strong>Workshop</strong> tab as usual. An asset will appear on your Balance Sheet, and an automatic expense transaction will be logged in Cash Flow for the &quot;purchase&quot; amount.</li><li>To offset this artificial expense (since you didn&#39;t physically spend cash now—the asset was bought in the past), go to the <strong>Cash Flow</strong> tab and create an income entry (such as <strong>Non-operating income</strong>) equal to the value of this asset. In the comment, specify: <em>“Correction for forgotten historical asset”</em>.</li></ol></div><p>That&#39;s it! Your database is configured, the calculations are synchronized, and both your Balance Sheet and Cash Flow Ledger reflect your true business reality.</p><hr><h2 id="🚀-base-pricing-settings" tabindex="-1">🚀 Base Pricing Settings <a class="header-anchor" href="#🚀-base-pricing-settings" aria-label="Permalink to &quot;🚀 Base Pricing Settings&quot;">​</a></h2><p>Before you proceed to create products (the <strong>Calculator</strong> tab), it is important to set your workshop&#39;s financial guidelines. Go to the <strong>Settings</strong> tab and set three primary parameters:</p><h3 id="_1-master-hourly-rate-currency-hour" tabindex="-1">1. Master Hourly Rate (Currency/Hour) <a class="header-anchor" href="#_1-master-hourly-rate-currency-hour" aria-label="Permalink to &quot;1. Master Hourly Rate (Currency/Hour)&quot;">​</a></h3><p>This is the cost of one hour of the master&#39;s labor.</p><ul><li><strong>If you hire assistants:</strong> Enter their average hourly wage here. The program will treat this money as a direct expense and factor it strictly into the cost price.</li><li><strong>If you work for yourself (solo artisan):</strong> You can set the rate to <code>0</code>. In this case, you won&#39;t have to make extra transactions to pay a &quot;salary&quot; to yourself. However, keep in mind: if your labor rate is zero, the value of your labor must be factored into your <em>global markup</em> percentage.</li></ul><h3 id="_2-global-markup" tabindex="-1">2. Global Markup (%) <a class="header-anchor" href="#_2-global-markup" aria-label="Permalink to &quot;2. Global Markup (%)&quot;">​</a></h3><p>This is your margin multiplier. The program automatically applies this percentage to the net cost price of an item (materials + labor + overhead costs) to calculate the <strong>Recommended Retail Price</strong> for you.</p><h3 id="_3-overhead-expenses-global-norms" tabindex="-1">3. Overhead Expenses (Global Norms) <a class="header-anchor" href="#_3-overhead-expenses-global-norms" aria-label="Permalink to &quot;3. Overhead Expenses (Global Norms)&quot;">​</a></h3><p>Overheads are the indirect costs of running your workshop: electricity, rent, consumables, or software. In Settings, you establish their baseline level. They can be of two types:</p><ul><li><strong>Percentage (%):</strong> Calculated as a percentage of the item&#39;s raw cost (materials and labor).</li><li><strong>Fixed (Currency):</strong> A flat monetary sum added to each produced item.</li></ul><p><strong>Customizing Within Recipes:</strong> You won&#39;t have to change your global settings every time different products have different manufacturing costs. When creating a recipe for a specific item in the <strong>Calculator</strong>, the program will offer you a smart panel of multipliers:</p><ul><li>If a product consumes twice as much electricity and glue, simply set its overhead coefficient to <code>2.0</code> (the program will multiply the global norm by two).</li><li>If a simple keychain does not require heavy machinery at all, set the coefficient to <code>0</code>, and these overhead costs will not be factored into its cost price.</li></ul><p>Once you have configured these parameters, your system is fully ready. You can now switch to the <strong>Calculator</strong> tab and create your first product recipes.</p>',34)])])}const g=t(s,[["render",i]]);export{d as __pageData,g as default};
